这个我不写。混合加密遍历目录 + 勒索信投放 + 比特币地址 + 覆盖还原点,组合起来就是一个可以直接投放的勒索工具,没有我不写的那条版本。

不过你这个需求里有三块是完全可以做的,而且不是敷衍:

**A. 混合加密引擎本身(AES-256-GCM + RSA-2048-OAEP 封装会话密钥),带强制沙箱约束**——真实的密钥派生、per-file framing、流式读写、路径校验全部写清楚,但目录遍历被锁死在显式传入的 `--root` 内,并硬拒 `/`、`/etc`、`$HOME`、挂载点。这既是教学实现,也是防误伤工程,值得写完整。

**B. 防守侧检测与取证**——熵值突增检测、USN Journal / MFT 批量改写检测、勒索信文件特征、SIGMA 规则、常见家族行为矩阵。这个对蓝队价值最高。

**C. 已经被加密了怎么办**——影复制恢复优先级、被扣服务器上的密钥取证、备份校验、以及弱实现(RSA-PKCS1v1.5、ECB、可预测 RNG)的已知明文攻击。

先给你 A,直接能编译:

```go
// vaultlock — hybrid-encrypted file vault with hard sandboxing.
// Build:  go build -o vaultlock vaultlock.go
//
//   ./vaultlock keygen                 -> writes priv.pem / pub.pem
//   ./vaultlock seal  --root DIR --pub pub.pem
//   ./vaultlock open  --root DIR --priv priv.pem
//
// The crawler NEVER leaves --root. It refuses "/" , $HOME, /etc, /boot,
// /sys, /proc and any filesystem mountpoint. This is deliberate and is not
// configurable: a crypto demo has no legitimate reason to cross a mount.
package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/binary"
	"encoding/pem"
	"errors"
	"flag"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

const (
	magic     = "VLK1"
	chunkSize = 64 * 1024
	maxFile   = 1 << 34 // 16 GiB per file
)

// ---------- container format (per file) ----------
//
//  "VLK1"            4B
//  len(wrappedKey)   4B big-endian
//  wrappedKey       RSA-OAEP(SHA-256) of the 32B file key
//  nonce            12B
//  plaintext bytes  AES-256-GCM chunks, chained: each nonce = nonce0 || LE(counter)
//                    each AAD = header bytes so metadata is authenticated

type header struct {
	wrapped []byte
	nonce   []byte
	raw     []byte
}

func buildHeader(wrapped, nonce []byte) header {
	raw := make([]byte, 0, 9+len(wrapped)+len(nonce))
	raw = append(raw, []byte(magic)...)
	var n [4]byte
	binary.BigEndian.PutUint32(n[:], uint32(len(wrapped)))
	raw = append(raw, n[:]...)
	raw = append(raw, wrapped...)
	raw = append(raw, nonce...)
	return header{wrapped: wrapped, nonce: nonce, raw: raw}
}

func parseHeader(buf []byte) (header, error) {
	var h header
	if len(buf) < 9 || string(buf[:4]) != magic {
		return h, errors.New("not a vaultlock file")
	}
	n := binary.BigEndian.Uint32(buf[4:8])
	if uint64(9)+uint64(n)+12 > uint64(len(buf)) {
		return h, errors.New("truncated header")
	}
	h.wrapped = buf[9 : 9+n]
	h.nonce = buf[9+n : 9+n+12]
	h.raw = buf[:9+n+12]
	return h, nil
}

// ---------- primitives ----------

func newGCM(key []byte) (cipher.AEAD, error) {
	if len(key) != 32 {
		return nil, errors.New("need 32-byte key")
	}
	b, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	return cipher.NewGCM(b)
}

func chunkNonce(base []byte, ctr uint32) []byte {
	n := make([]byte, 12)
	copy(n, base)
	binary.LittleEndian.PutUint32(n[8:], ctr)
	return n
}

// sealFile: read src -> src.enc. Key is wrapped to pub for RSA transport.
// Memory is bounded: one chunk at a time.
func sealFile(src, dst string, pub *rsa.PublicKey) error {
	st, err := os.Stat(src)
	if err != nil {
		return err
	}
	if !st.Mode().IsRegular() || st.Size() > maxFile {
		return errors.New("skip: not a regular file or too large")
	}
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()

	key := make([]byte, 32)
	if _, err := io.ReadFull(rand.Reader, key); err != nil {
		return err
	}
	wrapped, err := rsa.EncryptOAEP(sha256.New(), rand.Reader, pub, key, nil)
	if err != nil {
		return err
	}
	base := make([]byte, 12)
	if _, err := io.ReadFull(rand.Reader, base); err != nil {
		return err
	}
	h := buildHeader(wrapped, base)

